{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Aliskiren has an absolute oral bioavailability of 2.6% in humans, with over 97% of the ingested dose excreted unchanged in feces, indicating very poor absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Alvimopan has an estimated absolute oral bioavailability of only 6% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Melagatran has an oral bioavailability of 3–7% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Epanolol showed a mean absolute oral bioavailability of 7.06 ± 3.15% in fasted volunteers after a 200 mg oral solution.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Argatroban is available only as an injectable product because of its poor oral bioavailability in humans.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All available experimental records report low oral bioavailability (<10%) in humans across multiple drug scaffolds. These consistent low-F outcomes, together with the query's extreme size and polarity, support an absolute oral bioavailability below the 20% threshold.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement is available for the query molecule.",
    "No close structural analogue with measured oral bioavailability is present; the retrieved records are small-molecule drugs rather than large peptide-like structures, so transferability is limited but directionally consistent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

